//! The public twin in other formats must reconcile to the same answer: the bank statement as a
//! PDF and the main receivables as a CNAB 240 return (`testdata/golden/vantara-twin-pdf-cnab240`,
//! generated by `testdata/synth/formatos_financeiros.py`), and every twin file inside a ZIP.
//! Files that cannot take part in a run never change the answer and always leave a warning.

use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};

use dm_eval::{find_golden_dirs, find_twin_dir, load, run_golden};
use dm_recon::{run_dir, EngineConfig, Golden};

fn twin() -> PathBuf {
    find_twin_dir(Path::new(env!("CARGO_MANIFEST_DIR")))
        .unwrap_or_else(|| panic!("testdata/golden/vantara-twin não encontrado"))
}

fn variant() -> PathBuf {
    twin().with_file_name("vantara-twin-pdf-cnab240")
}

fn read(path: &Path) -> Vec<u8> {
    std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

#[test]
fn pdf_statement_and_cnab240_receivables_score_100() {
    let run =
        run_golden(&variant(), &EngineConfig::default(), 10).unwrap_or_else(|e| panic!("{e}"));
    assert!(
        run.scorecard.perfect(),
        "variação PDF + CNAB 240:\n{}",
        run.scorecard.report()
    );
    assert!(run.identical, "dez execuções deram resultados diferentes");
    assert_eq!(
        run.scorecard.summary(),
        "18/18 linhas, 17/17 títulos, 23/23 achados"
    );
    assert_eq!(
        (run.scorecard.totals.ok, run.scorecard.totals.total),
        (11, 11)
    );
    let ds = run_dir(&variant(), &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset;
    assert!(ds.warnings.is_empty(), "{:?}", ds.warnings);
}

/// The variant's answer key is the twin's, with only the case name and the two file names
/// changed; the copied inputs are byte-identical.
#[test]
fn variant_keeps_the_twin_answer_key_and_inputs() {
    let twin_expected = load(&twin().join("expected.yaml")).unwrap_or_else(|e| panic!("{e}"));
    let mut variant_expected =
        load(&variant().join("expected.yaml")).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(
        variant_expected.sources.get("protheus").map(String::as_str),
        Some("01_retorno_cobranca_jul2026.ret")
    );
    assert_eq!(
        variant_expected.sources.get("bank").map(String::as_str),
        Some("03_extrato_bancario_jul2026.pdf")
    );
    variant_expected.sources = twin_expected.sources.clone();
    variant_expected.case = twin_expected.case.clone();
    assert_eq!(variant_expected.to_json(), twin_expected.to_json());
    for name in [
        "02_titulos_unidade_norte_omie_jul2026.csv",
        "04_caixa_de_entrada_contas_a_pagar.txt",
    ] {
        assert_eq!(
            read(&variant().join(name)),
            read(&twin().join(name)),
            "{name} difere do gêmeo"
        );
    }
    assert!(find_golden_dirs(Path::new(env!("CARGO_MANIFEST_DIR"))).contains(&variant()));
}

fn twin_inputs() -> BTreeMap<String, Vec<u8>> {
    std::fs::read_dir(twin())
        .unwrap_or_else(|e| panic!("{e}"))
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| {
            p.extension()
                .and_then(|x| x.to_str())
                .is_some_and(|x| x == "csv" || x == "txt")
        })
        .map(|p| {
            let name = p
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default()
                .to_string();
            (name, read(&p))
        })
        .collect()
}

#[test]
fn twin_inside_a_zip_scores_100() {
    let mut buf = std::io::Cursor::new(Vec::new());
    {
        let mut w = zip::ZipWriter::new(&mut buf);
        let opts = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Deflated);
        for (name, bytes) in twin_inputs() {
            w.start_file(format!("julho/{name}"), opts)
                .unwrap_or_else(|e| panic!("{e}"));
            w.write_all(&bytes).unwrap_or_else(|e| panic!("{e}"));
        }
        w.finish().unwrap_or_else(|e| panic!("{e}"));
    }
    let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(dir.path().join("pacote.zip"), buf.into_inner())
        .unwrap_or_else(|e| panic!("{e}"));
    let mut expected: Golden =
        load(&twin().join("expected.yaml")).unwrap_or_else(|e| panic!("{e}"));
    for file in expected.sources.values_mut() {
        *file = format!("pacote.zip/julho/{file}");
    }
    std::fs::write(dir.path().join("expected.yaml"), expected.to_json())
        .unwrap_or_else(|e| panic!("{e}"));
    let run = run_golden(dir.path(), &EngineConfig::default(), 2).unwrap_or_else(|e| panic!("{e}"));
    assert!(
        run.scorecard.perfect(),
        "gêmeo no zip:\n{}",
        run.scorecard.report()
    );
    assert!(run.identical);
}

/// Unusable files next to the twin change nothing in the answer and each one is named in the
/// warnings, with its reason.
#[test]
fn unusable_files_are_reported_and_change_nothing() {
    let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    for (name, bytes) in twin_inputs() {
        std::fs::write(dir.path().join(name), bytes).unwrap_or_else(|e| panic!("{e}"));
    }
    std::fs::copy(
        twin().join("expected.yaml"),
        dir.path().join("expected.yaml"),
    )
    .unwrap_or_else(|e| panic!("{e}"));
    let golden = twin().parent().map(Path::to_path_buf).unwrap_or_default();
    for (from, to) in [
        (
            "pdf/extrato_digitalizado.pdf",
            "05_extrato_digitalizado.pdf",
        ),
        (
            "sped/efd_icms_ipi_jul2026.txt",
            "06_efd_icms_ipi_jul2026.txt",
        ),
        (
            "cnab240/retorno_pagamentos.ret",
            "07_retorno_pagamentos.ret",
        ),
    ] {
        std::fs::copy(golden.join(from), dir.path().join(to)).unwrap_or_else(|e| panic!("{e}"));
    }
    std::fs::write(dir.path().join("08_vazio.csv"), b"").unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(dir.path().join("09_binario.bin"), [0u8, 159, 146, 150])
        .unwrap_or_else(|e| panic!("{e}"));
    let run = run_golden(dir.path(), &EngineConfig::default(), 1).unwrap_or_else(|e| panic!("{e}"));
    assert!(run.scorecard.perfect(), "{}", run.scorecard.report());
    let ds = run_dir(dir.path(), &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset;
    let warnings = ds.warnings.join("\n");
    for (file, reason) in [
        (
            "05_extrato_digitalizado.pdf",
            "OCR ainda não está disponível",
        ),
        (
            "06_efd_icms_ipi_jul2026.txt",
            "não entrou nesta conciliação",
        ),
        ("07_retorno_pagamentos.ret", "não entrou nesta conciliação"),
        ("07_retorno_pagamentos.ret", "segmento ou tipo 'O'"),
        ("08_vazio.csv", "arquivo vazio"),
        ("09_binario.bin", "formato não reconhecido"),
    ] {
        assert!(
            ds.warnings
                .iter()
                .any(|w| w.starts_with(&format!("{file}: ")) && w.contains(reason)),
            "sem aviso de {file} ({reason}):\n{warnings}"
        );
    }
}

/// A folder with nothing usable fails with every file's reason in the error.
#[test]
fn nothing_usable_explains_why() {
    let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    let golden = twin().parent().map(Path::to_path_buf).unwrap_or_default();
    std::fs::copy(
        golden.join("pdf/extrato_digitalizado.pdf"),
        dir.path().join("extrato.pdf"),
    )
    .unwrap_or_else(|e| panic!("{e}"));
    let err = run_dir(dir.path(), &EngineConfig::default())
        .err()
        .map(|e| e.to_string())
        .unwrap_or_default();
    assert!(err.contains("nenhuma fonte reconhecida"), "{err}");
    assert!(
        err.contains("extrato.pdf: PDF sem camada de texto"),
        "{err}"
    );
}
